import { Threads } from "@amodx/threads";
import ArchiveSector from "./Functions/Sector/ArchiveSector";
import { WorldRegister } from "../WorldRegister";
import ImportSector from "./Functions/Sector/ImportSector";
import { compressBinaryObject, expandBinaryObject, } from "../../Util/BinaryObject";
function runArchiveSector(location) {
    const sector = WorldRegister.sectors.get(...location);
    if (!sector) {
        console.warn([...location], WorldRegister._dimensions.get(0).sectors, sector);
        throw new Error(`Sector at location ${location.toString()} does not exist`);
    }
    const archived = ArchiveSector({
        location,
    });
    const transfers = [];
    for (const section of archived.sections) {
        if (typeof section == "string")
            continue;
        if (ArrayBuffer.isView(section.buffers.id?.buffer))
            transfers.push(section.buffers.id.buffer);
        if (ArrayBuffer.isView(section.buffers.light?.sun?.buffer))
            transfers.push((section.buffers.light?.sun).buffer);
        if (ArrayBuffer.isView(section.buffers.light?.red?.buffer))
            transfers.push((section.buffers.light?.red).buffer);
        if (ArrayBuffer.isView(section.buffers.light?.green?.buffer))
            transfers.push((section.buffers.light?.green).buffer);
        if (ArrayBuffer.isView(section.buffers.light?.blue?.buffer))
            transfers.push((section.buffers.light?.blue).buffer);
        if (ArrayBuffer.isView(section.buffers.secondary?.buffer))
            transfers.push(section.buffers.secondary.buffer);
        if (!section.palettes)
            continue;
        if (section.palettes.id)
            transfers.push(section.palettes.id.buffer);
    }
    return [archived, transfers];
}
export default function InitTasks(props) {
    Threads.registerTask("archive-sector", async (location) => {
        return runArchiveSector(location);
    });
    Threads.registerTask("archive-sector-binary", async (location) => {
        const [archived] = runArchiveSector(location);
        try {
            const compressed = await compressBinaryObject(archived);
            return [compressed, [compressed]];
        }
        catch (error) {
            console.log(archived);
            console.error(error);
        }
        return [null, []];
    });
    Threads.registerTask("import-sector", async (archived) => {
        const importedSector = ImportSector(archived, {});
        props.worldThread.runTask("load-sector", [
            [
                WorldRegister.dimensions._dimensionMap.get(archived.dimension) || 0,
                archived.position.x,
                archived.position.y,
                archived.position.z,
            ],
            importedSector.buffer,
        ], importedSector.buffer instanceof ArrayBuffer
            ? [importedSector.buffer]
            : []);
    });
    Threads.registerTask("import-sector-binary", async ([location, archived]) => {
        const archivedSector = await expandBinaryObject(archived, true);
        const importedSector = ImportSector(archivedSector, {});
        props.worldThread.runTask("load-sector", [location, importedSector.buffer], importedSector.buffer instanceof ArrayBuffer
            ? [importedSector.buffer]
            : []);
    });
}
